param([Parameter(Mandatory=$true)][ValidateSet('identify','identify-folder','adapters','plan-cpp','sync-names')][string]$Command,[string]$InputFile,[string]$Db,[string]$Output,[string]$TitleDb,[string]$SourcesRoot,[switch]$Apply,[switch]$IncludeDiscs)
$ErrorActionPreference='Stop'; $cli=Join-Path $PSScriptRoot 'recomp_bridge.py'; $args2=@('-3',$cli,$Command); if($InputFile){$args2+=@('--input',$InputFile)}; if($Db){$args2+=@('--db',$Db)}; if($Output){$args2+=@('--output',$Output)}; if($TitleDb){$args2+=@('--title-db',$TitleDb)}; if($SourcesRoot){$args2+=@('--sources-root',$SourcesRoot)}; if($Apply){$args2+='--apply'}; if($IncludeDiscs){$args2+='--include-discs'}; & py @args2; if($LASTEXITCODE -ne 0){throw "Bridge command failed: $LASTEXITCODE"}
